    transition: translate 0.6s calc((var(--char) - 1) * var(--button-099-stagger) + var(--button-099-in-delay)) var(--button-099-ease-hover), transform 0.25s calc((var(--char) - 1) * var(--button-099-stagger) + var(--button-099-in-delay)) ease-out, opacity 0.15s calc((var(--char) - 1) * var(--button-099-stagger) + var(--button-099-in-delay)) ease-out;
  }






  /* Web credits reveal */
[data-web-credits="target"] {
  translate: 0 12rem;
  transition: translate 1s var(--button-099-ease-hover);
}

.footer_bottom:has([data-web-credits="button"] .button-099:is(:hover, :focus-visible)) [data-web-credits="target"] {
  translate: 0 0;
}
}

</style></div><div class="cursor-styles w-embed"><style>
@media (hover: hover) and (pointer: fine) {
  [data-cursor] .button-099 {
    transition: transform 0.3s cubic-bezier(0.625, 0.05, 0, 1), opacity 0.4s cubic-bezier(0.625, 0.05, 0, 1);
    transform: translateX(0%) scale(0.9) rotate(0.001deg);
  }
  
  [data-cursor="active"] .button-099 {
    opacity: 1; 
    transform: translateX(0%) scale(1) rotate(0.001deg);
  }
  
  [data-cursor="active-edge"] .button-099 {
    opacity: 1; 
    transform: translateX(-100%) scale(1) rotate(0.001deg);
  }
}

@media (hover: none) and (pointer: coarse) {
  .cursor {
    display: none;
  }
}




  [data-sound-cursor] [data-mute] {
  display: none;
}

[data-sound-cursor][data-player-muted="false"] [data-unmute] {
  display: none;
}

[data-sound-cursor][data-player-muted="false"] [data-mute] {
  display: block;
}
</style></div><div class="media-styles w-embed"><style>
/* Media cards — image saturation + scale on hover */
.media-image {
  transform: scale(1);
  transition:
    filter 0.4s cubic-bezier(0.25, 0.1, 0.25, 1),
    transform 0.4s cubic-bezier(0.33, 1, 0.68, 1); /* hover-out */
  will-change: transform;
}
@media (hover: hover) and (pointer: fine) {
  .media-card:hover .media-image {
    filter: saturate(1);
    transform: scale(1.04);
    transition:
      filter 0.4s cubic-bezier(0.25, 0.1, 0.25, 1),
      transform 0.6s cubic-bezier(0.22, 1, 0.36, 1); /* hover-in */
  }
}
</style></div><div class="logo-wall-styles w-embed"><style>
/* ── CONFIG ─────────────────────────────── */
:root {
  --logo-wall-row-gap: 2rem;
  --logo-wall-offset: 5.4rem; /* top indent outer/middle columns */
}
[data-logo-wall="list"] {
  display: grid;
  row-gap: var(--logo-wall-row-gap);
  align-items: center;
  justify-items: center;
  padding-bottom: var(--logo-wall-offset);
}

/* ── Desktop / tablet: 7 cols, items on 1, 2, 6, 7 ── */
@media (min-width: 768px) {
  [data-logo-wall="list"] {
    grid-template-columns: repeat(7, 1fr);
  }
  [data-logo-wall="item"]:nth-child(4n + 1) { grid-column: 1; }
  [data-logo-wall="item"]:nth-child(4n + 2) { grid-column: 2; }
  [data-logo-wall="item"]:nth-child(4n + 3) { grid-column: 6; }
  [data-logo-wall="item"]:nth-child(4n)     { grid-column: 7; }
  /* Indent: shift the outer columns down */
  [data-logo-wall="item"]:nth-child(4n + 1),
  [data-logo-wall="item"]:nth-child(4n) {
    transform: translateY(var(--logo-wall-offset));
  }
  /* Orphan pair: exactly 2 leftover items go to cols 2 and 6 */
  [data-logo-wall="item"]:nth-child(4n + 1):nth-last-child(2) {
    grid-column: 2;
    transform: none;
  }
  [data-logo-wall="item"]:nth-child(4n + 2):nth-last-child(1) {
    grid-column: 6;
  }
}

/* ── Mobile: 3 filled columns, middle column indented ── */
@media (max-width: 767px) {
  [data-logo-wall="list"] {
    grid-template-columns: repeat(3, 1fr);
  }
  [data-logo-wall="item"]:nth-child(3n + 2) {
    transform: translateY(var(--logo-wall-offset));
  }
}
</style></div><div class="bunny-styles w-embed"><style>
/* Animation */
[data-bunny-background-init] :is(.bunny-bg__placeholder, .bunny-bg__loading) {
  transition: opacity 0.3s linear, visibility 0.3s linear;
}

/* Placeholder */
[data-bunny-background-init][data-player-status="playing"] .bunny-bg__placeholder,
[data-bunny-background-init][data-player-status="paused"] .bunny-bg__placeholder,
[data-bunny-background-init][data-player-activated="true"][data-player-status="ready"] .bunny-bg__placeholder {
  opacity: 0;
  visibility: hidden;
}

/* Play/Pause */
[data-bunny-background-init][data-player-status="playing"] .bunny-bg__play-svg,
[data-bunny-background-init][data-player-status="loading"] .bunny-bg__play-svg {
  display: none;
}

[data-bunny-background-init][data-player-status="playing"] .bunny-bg__pause-svg,
[data-bunny-background-init][data-player-status="loading"] .bunny-bg__pause-svg{
  display: block;
}

/* Loading */
[data-bunny-background-init][data-player-status="loading"] .bunny-bg__loading {
  opacity: 1;
  visibility: visible;
}


@media (hover: none) and (pointer: coarse) {
  .bunny-bg__sound { display: none; }
}
</style></div><div data-grab-cursor="" data-cursor="" class="cursor"><div data-button-099="" class="button-099 is-cursor"><span class="button-099__bg"></span><span class="button-099__inner"><div class="button-099__content"><span aria-hidden="true" data-button-099-text="" data-cursor-text-target="" class="button-099__text is--default">drag</span><svg xmlns="http://www.w3.org/2000/svg" width="100%" viewBox="0 0 13 17" fill="none" class="button-099__icon is-drag"><path d="M9 0H4C1.79086 0 0 1.79086 0 4V10.8989C0 11.6861 0.232313 12.4559 0.667836 13.1117L2.06317 15.2128C2.80445 16.3291 4.05539 17 5.39534 17H7.60466C8.94461 17 10.1956 16.3291 10.9368 15.2128L12.3322 13.1117C12.7677 12.4559 13 11.6861 13 10.8989V4C13 1.79086 11.2091 0 9 0Z" fill="var(--_colors---black--100)"></path><path d="M4 4.5H9" stroke="var(--_colors---primary--100)" stroke-linecap="round"></path><path d="M4 7.5H9" stroke="var(--_colors---primary--100)" stroke-linecap="round"></path></svg></div><div class="button-099__content"><span aria-hidden="true" data-cursor-text-target="" class="button-099__text is--hover">drag</span><svg xmlns="http://www.w3.org/2000/svg" width="100%" viewBox="0 0 13 17" fill="none" class="button-099__icon is-drag"><path d="M9 0H4C1.79086 0 0 1.79086 0 4V10.8989C0 11.6861 0.232313 12.4559 0.667836 13.1117L2.06317 15.2128C2.80445 16.3291 4.05539 17 5.39534 17H7.60466C8.94461 17 10.1956 16.3291 10.9368 15.2128L12.3322 13.1117C12.7677 12.4559 13 11.6861 13 10.8989V4C13 1.79086 11.2091 0 9 0Z" fill="var(--_colors---black--100)"></path><path d="M4 4.5H9" stroke="var(--_colors---primary--100)" stroke-linecap="round"></path><path d="M4 7.5H9" stroke="var(--_colors---primary--100)" stroke-linecap="round"></path></svg></div></span></div></div><div data-click-cursor="" data-cursor="" class="cursor"><div data-button-099="" class="button-099 is-cursor"><span class="button-099__bg"></span><span class="button-099__inner"><div class="button-099__content"><span aria-hidden="true" data-button-